mkdir -p /tmp/bot-test && cat > /tmp/bot-test/test.mjs <<'EOF'
import assert from 'node:assert/strict';
import { mkdtemp, writeFile, readdir } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { execFileSync, spawn } from 'node:child_process';

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/baseline-g3-2/bot.mjs';
const STATE = join(await mkdtemp(join(tmpdir(), 'bot-state-')), 'nested', 'state'); // does not exist yet
process.env.STATE_DIR = STATE;
const bot = await import(BOT);
const now = new Date();

// 1. fresh address: marketing and receipt allowed
let r = await bot.mayEmail('<EMAIL>', 'marketing', now);
assert.equal(r.allowed, true); console.log('fresh marketing:', r.reason);

// 2. unsubscribe with messy casing/spaces; marketing blocked, receipt still allowed
await bot.unsubscribe('  <EMAIL> ');
r = await bot.mayEmail('<EMAIL>', 'marketing', now);
assert.equal(r.allowed, false); console.log('after unsub:', r.reason);
r = await bot.mayEmail(' <EMAIL>', 'receipt', now);
assert.equal(r.allowed, true); console.log('receipt after unsub:', r.reason);

// 3. resubscribe re-enables marketing; unsubscribe again re-blocks
await bot.resubscribe('<EMAIL>');
assert.equal((await bot.mayEmail('<EMAIL>', 'marketing', now)).allowed, true);
await bot.unsubscribe('<EMAIL>');
assert.equal((await bot.mayEmail('<EMAIL>', 'marketing', now)).allowed, false);

// 4. bad inputs throw (never a silent allow)
await assert.rejects(bot.mayEmail('<EMAIL>', 'promo', now), /unknown kind/);
await assert.rejects(bot.mayEmail('<EMAIL>', 'marketing', '2026-01-01'), /valid Date/);
await assert.rejects(bot.mayEmail('not-an-email', 'marketing', now), /valid email/);
await assert.rejects(bot.unsubscribe(42), /must be a string/);

// 5. persistence across a fresh process (simulates restart)
const child = (code) => new Promise((res, rej) => {
  const p = spawn(process.execPath, ['--input-type=module', '-e', code], { env: { ...process.env, STATE_DIR: STATE } });
  let out = ''; p.stdout.on('data', d => out += d); p.stderr.on('data', d => out += d);
  p.on('close', c => c === 0 ? res(out.trim()) : rej(new Error(out)));
});
const fresh = await child(`const b = await import(${JSON.stringify(BOT)}); console.log((await b.mayEmail('<EMAIL>','marketing',new Date())).allowed)`);
assert.equal(fresh, 'false'); console.log('new process sees unsub:', fresh);

// 6. concurrency: 60 processes unsubscribe different and same addresses at once
const emails = Array.from({ length: 20 }, (_, i) => `user${i}@shop.test`);
const jobs = [];
for (let i = 0; i < 60; i++) {
  const e = emails[i % emails.length];
  jobs.push(child(`const b = await import(${JSON.stringify(BOT)}); await b.unsubscribe(${JSON.stringify(e)})`));
}
await Promise.all(jobs);
for (const e of emails) {
  assert.equal((await bot.mayEmail(e, 'marketing', now)).allowed, false, e);
}
const files = await readdir(join(STATE, 'suppression'));
console.log('concurrent: files =', files.length, '(expect 21 incl. <EMAIL>)');
assert.equal(files.length, 21);

// 7. corrupt record fails closed for marketing, receipts still go
await writeFile(join(STATE, 'suppression', (await readdir(join(STATE, 'suppression'))).find(() => true)), 'not json');
const cfiles = await readdir(join(STATE, 'suppression'));
let blocked = 0;
for (const f of cfiles) { }
// corrupt a fresh address instead, to be explicit
await bot.unsubscribe('corrupt@shop.test');
const { createHash } = await import('node:crypto');
const h = createHash('sha256').update('corrupt@shop.test').digest('hex');
await writeFile(join(STATE, 'suppression', h + '.jsonl'), '\n{"event":"unsubscribe","email":"corrupt@shop.test","at":"x"}\n{"half', 'utf8');
r = await bot.mayEmail('corrupt@shop.test', 'marketing', now);
assert.equal(r.allowed, false); console.log('corrupt:', r.reason);
r = await bot.mayEmail('corrupt@shop.test', 'receipt', now);
assert.equal(r.allowed, true);

// 8. write after a half-written line lands on its own line
await bot.resubscribe('corrupt@shop.test');
r = await bot.mayEmail('corrupt@shop.test', 'marketing', now);
console.log('after resubscribe on corrupt file:', r.allowed, '(still false: corrupt line stays)');
assert.equal(r.allowed, false);

console.log('ALL PASS');
EOF
